SELECT 'gongkao', '排列组合', 'kp-xc-quantity-math-operation-permutation-combination', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "排列组合"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心结论：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "排列组合是数量关系的核心基础，分类加法和分步乘法是基本原理，排列和组合的区别在于是否考虑顺序。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、知识要点"}]}, {"type": "orderedList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "分类加法原理：完成一件事有n类方法，各类方法数分别为m1,m2,...,mn，则总方法数 = m1+m2+...+mn"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "分步乘法原理：完成一件事需n个步骤，各步方法数分别为m1,m2,...,mn，则总方法数 = m1×m2×...×mn"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "排列Anm = n!/(n-m)!，从n个不同元素中取m个排成一列，顺序有关"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "组合Cnm = n!/[m!(n-m)!]，从n个不同元素中取m个组成一组，顺序无关"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "常用技巧：捆绑法（相邻问题）、插空法（不相邻问题）、隔板法（相同元素分组）"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、解题方法"}]}, {"type": "orderedList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "先判断是排列还是组合：有序选排列，无序选组合"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "先分类再分步：先确定用加法还是乘法，再计算每类/每步的方法数"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "特殊元素优先处理：先安排有限制的元素，再安排无限制的"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "正难则反：直接计算困难时，用总数减去反面情况"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、易错点"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "混淆排列和组合：看到\"选\"就用组合，但\"选出来排成一排\"要用排列"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "重复计数：捆绑法忘记内部排列，或插空法算错空位数"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "分类不互斥：用加法原理时各类情况必须互斥，否则要减去重复"}]}]}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#eff6ff", "borderColor": "#3b82f6", "icon": "📊"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "刷题建议：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "排列组合是概率和容斥的基础，必须先掌握。建议分类练习：基础计算、捆绑插空、隔板法、分组分配。"}]}]}]}$$ AS jsonb), NULL, '数量关系-数学运算-排列组合的核心知识点和解题方法。', category_node.id, CAST('["数量关系", "数学运算", "排列组合"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_quantity_math_operation_permutation_combination", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
